#!/usr/bin/env python3
"""Payment reconciliation script.

Usage:
    python3 /app/reconcile.py <path/to/input.csv>

The script reads a CSV file described in the problem statement, applies the
business rules, and prints a single JSON object to stdout. All diagnostics are
sent to stderr.
"""

import sys
import csv
import json
import datetime
import decimal
import re

# Regular expression for validating the amount (up to two decimal places,
# no sign, no exponent, no NaN/inf).
_AMOUNT_RE = re.compile(r"^(?:0|[1-9]\d*)(?:\.\d{1,2})?$")


def _parse_timestamp(ts: str) -> datetime.datetime | None:
    """Parse ISO‑8601 timestamp with Z or ±HH:MM offset.

    Returns a timezone‑aware datetime on success or None if the format is invalid.
    """
    try:
        if ts.endswith('Z'):
            ts = ts[:-1] + '+00:00'
        dt = datetime.datetime.fromisoformat(ts)
        if dt.tzinfo is None:
            return None
        return dt
    except Exception:
        return None


def _is_valid_row(row: list[str]) -> bool:
    """Validate a CSV row according to the specification.
    Returns True if the row is well‑formed, otherwise False.
    """
    if len(row) != 4:
        return False
    tx_id, timestamp, amount, status = row
    if not (tx_id and timestamp and amount and status):
        return False
    if _parse_timestamp(timestamp) is None:
        return False
    if not _AMOUNT_RE.fullmatch(amount):
        return False
    if status not in {"SUCCESS", "FAILED", "PENDING"}:
        return False
    return True


def main() -> int:
    if len(sys.argv) != 2:
        print("Usage: python3 /app/reconcile.py <path/to/input.csv>", file=sys.stderr)
        return 2

    input_path = sys.argv[1]
    latest: dict[str, tuple[datetime.datetime, decimal.Decimal, str]] = {}
    try:
        with open(input_path, newline='') as csvfile:
            reader = csv.reader(csvfile)
            # Skip header
            try:
                next(reader)
            except StopIteration:
                pass
            for row in reader:
                if not _is_valid_row(row):
                    continue
                tx_id, ts_str, amount_str, status = row
                ts = _parse_timestamp(ts_str)
                amt = decimal.Decimal(amount_str)
                if tx_id in latest:
                    if ts > latest[tx_id][0]:
                        latest[tx_id] = (ts, amt, status)
                else:
                    latest[tx_id] = (ts, amt, status)
    except FileNotFoundError:
        print(f"File not found: {input_path}", file=sys.stderr)
        return 1
    except Exception as e:
        print(f"Error processing file: {e}", file=sys.stderr)
        return 1

    total_valid = decimal.Decimal('0')
    valid_count = 0
    failed_count = 0
    for _, amt, status in latest.values():
        if status == 'SUCCESS':
            total_valid += amt
            valid_count += 1
        elif status == 'FAILED':
            failed_count += 1
        # PENDING ignored
    total_valid = total_valid.quantize(decimal.Decimal('0.01'))
    result = {
        "total_valid_amount": float(total_valid),
        "valid_count": valid_count,
        "failed_count": failed_count,
    }
    json.dump(result, sys.stdout, separators=(",", ":"))
    sys.stdout.write('\n')
    return 0

if __name__ == "__main__":
    sys.exit(main())
EOF
